INSERT INTO bugs (id, bug_id, title, severity, module, status, discoverer, assignee, created_date, deadline, solution, created_at, updated_at) VALUES (34, 'BUG1786583994266', 'AI检测', '一般', 'MES功能', '解决关闭', '崔猛', '肖瑞森', '2026-01-09', '2026-01-16', '现状:MES防呆功能已完成:AI模型需要做良率爬坡风险点:AI检测设备对光源要求高，AI检测位不能随意挪动【导致检测良率降低，还得多次优化】', '2026-08-13 01:20:27', '2026-08-13 01:20:27');
